import type { Location, Resolved, Route } from './config'
import { join } from 'node:path'
import { upstreamUrl } from './config'

// TLS-terminated hosts listen here behind the SNI switch on 443.
export const TLS_PORT = 8443
export const MAIN = 'main'

export interface Group {
  name: string
  routes: Route[]
}

// Where each generated file goes, relative to the config's dir.
export const paths = {
  compose: 'compose.yml',
  entrypoint: 'entrypoint.sh',
  nginx: 'nginx/nginx.conf',
  sni: 'nginx/sni.conf',
  main: 'nginx/main.conf',
  groupHttp: (group: string) => `nginx/http/${group}.conf`,
  groupSni: (group: string) => `nginx/sni/${group}.conf`,
  status: 'nginx/.status',
  reload: 'nginx/.reload',
  cert: (group: string) => `certs/${group}.pem`,
  key: (group: string) => `certs/${group}-key.pem`,
  logs: 'logs',
}

const HEADER = '# Generated by devproxy from its config: edit the config, then run `devproxy apply`.'
const indent = (lines: string[], by: string) => lines.map(line => line === '' ? line : `${by}${line}`)

// nginx matches a passthrough wildcard through a regex: *.app.localhost serves any depth below app.localhost.
function sniKey(host: string): string {
  return host.startsWith('*.') ? `~^.+\\.${host.slice(2).replaceAll('.', '\\.')}$` : host
}

// A container upstream is resolved per request through a variable, so the proxy starts and reloads while that stack is down; host.docker.internal comes from /etc/hosts, which nginx's resolver never reads, so it stays static.
function proxyTo(to: string, buffering: boolean | undefined): string[] {
  const url = upstreamUrl(to)
  const origin = `${url.protocol}//${url.host}`
  const pass = url.hostname === 'host.docker.internal'
    ? [`proxy_pass ${origin};`]
    : [`set $upstream ${origin};`, 'proxy_pass $upstream$request_uri;']

  return [
    ...pass,
    'proxy_http_version 1.1;',
    'proxy_set_header Host              $host;',
    'proxy_set_header X-Real-IP         $remote_addr;',
    'proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;',
    'proxy_set_header X-Forwarded-Proto $scheme;',
    'proxy_set_header X-Forwarded-Host  $host;',
    'proxy_set_header X-Forwarded-Port  443;',
    'proxy_set_header Upgrade           $http_upgrade;',
    'proxy_set_header Connection        $connection_upgrade;',
    ...url.protocol === 'https:' ? ['proxy_ssl_server_name on;'] : [],
    ...buffering === false ? ['proxy_buffering off;'] : [],
    'proxy_read_timeout 600s;',
  ]
}

function location(entry: Location): string[] {
  const body = entry.redirect === undefined ? proxyTo(entry.to!, entry.buffering) : [`return 302 ${entry.redirect}$is_args$args;`]

  return [
    ...entry.comment === undefined ? [] : [`# ${entry.comment}`],
    `location ${entry.path} {`,
    ...indent([...body, ...entry.lines ?? []], '    '),
    '}',
  ]
}

function server(route: Route, cert: string, key: string): string[] {
  return [
    ...route.comment === undefined ? [] : [`# ${route.comment}`],
    'server {',
    ...indent([
      `listen ${TLS_PORT} ssl;`,
      'http2 on;',
      `server_name ${route.host};`,
      ...route.keepaliveRequests === undefined ? [] : [`keepalive_requests ${route.keepaliveRequests};`],
      '',
      `ssl_certificate     ${cert};`,
      `ssl_certificate_key ${key};`,
      ...route.lines === undefined ? [] : ['', ...route.lines],
      '',
      ...[...route.locations ?? [], { path: '/', to: route.to, ...route.buffering === undefined ? {} : { buffering: route.buffering } }].flatMap(entry => [...location(entry), '']).slice(0, -1),
    ], '    '),
    '}',
  ]
}

// The server blocks of one group's terminated routes; plain http on those hosts is answered by the default redirect.
export function renderHttp(config: Resolved, group: Group): string {
  const routes = group.routes.filter(route => route.passthrough !== true)
  const cert = join(config.dir, paths.cert(group.name))
  const key = join(config.dir, paths.key(group.name))

  return `${[HEADER, `# group ${group.name}`, '', ...routes.flatMap(route => [...server(route, cert, key), ''])].join('\n').trimEnd()}\n`
}

export function renderGroupSni(group: Group): string {
  const lines = group.routes.filter(route => route.passthrough === true).map(route => `${sniKey(route.host)} ${route.to};`)

  return `${[HEADER, `# group ${group.name}, included at the top of the map in sni.conf`, ...lines].join('\n')}\n`
}

// Every TLS connection on 443 is switched by SNI: passthrough hosts go to their upstream as is, the rest to this nginx's own TLS servers. Groups come first, so their regexes win over the main routes'.
export function renderSni(config: Resolved): string {
  const main = config.routes.filter(route => route.passthrough === true).map(route => `${sniKey(route.host)} ${route.to};`)

  return `${[
    HEADER,
    '',
    'map $ssl_preread_server_name $devproxy_upstream {',
    ...indent([
      `include ${join(config.dir, 'nginx/sni')}/*.conf;`,
      ...main,
      `default 127.0.0.1:${TLS_PORT};`,
    ], '    '),
    '}',
    '',
    'server {',
    ...indent(['listen 443;', 'listen [::]:443;', 'ssl_preread on;', 'proxy_pass $devproxy_upstream;', 'proxy_timeout 10m;'], '    '),
    '}',
  ].join('\n')}\n`
}

export function renderNginx(config: Resolved): string {
  const at = (path: string) => join(config.dir, path)

  return `${HEADER}

user nginx;
worker_processes auto;
pid /tmp/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
    server_tokens off;
    client_body_temp_path /tmp/nginx-body;
    proxy_temp_path /tmp/nginx-proxy;

    # Docker's DNS: upstreams named after containers resolve per request, so a stack started after the proxy is reached without a reload.
    resolver 127.0.0.11 valid=10s ipv6=off;

    map $http_upgrade $connection_upgrade {
        default upgrade;
        ''      "";
    }

    log_format devproxy '$msec $remote_addr $host $scheme $status $request_time $body_bytes_sent $request_length "$upstream_addr" "$upstream_response_time" "$request" "$http_referer" "$http_user_agent"';

    access_log ${at(`${paths.logs}/access.log`)} devproxy;
    error_log  ${at(`${paths.logs}/error.log`)} warn;

    # Passthrough hosts only listen on 443, so plain http to any host is sent to https here.
    server {
        listen 80 default_server;
        listen [::]:80 default_server;
        server_name _;

        return 301 https://$host$request_uri;
    }

    # A browser reuses an HTTP/2 connection for any host the certificate covers, so a request can land on a server not meant for it: 421 makes the browser open a new connection.
    server {
        listen ${TLS_PORT} ssl default_server;
        http2 on;
        server_name _;

        ssl_certificate     ${at(paths.cert(MAIN))};
        ssl_certificate_key ${at(paths.key(MAIN))};

        return 421;
    }

    include ${at(paths.main)};
    include ${at('nginx/http')}/*.conf;
}

stream {
    resolver 127.0.0.11 valid=10s ipv6=off;

    log_format devproxy_stream '$remote_addr [$time_local] $protocol $status $bytes_sent $bytes_received $session_time "$ssl_preread_server_name" -> $upstream_addr';
    access_log ${at(`${paths.logs}/stream.log`)} devproxy_stream;

    include ${at(paths.sni)};
}
`
}

// The proxy's folder is mounted at its own path, so the absolute paths in the generated config mean the same thing inside the container.
export function renderCompose(config: Resolved): string {
  return `${HEADER}
name: ${config.name}

services:
  nginx:
    image: ${config.image}
    container_name: ${config.name}
    restart: unless-stopped
    entrypoint: ["/bin/sh", "${join(config.dir, paths.entrypoint)}"]
    environment:
      DEVPROXY_CONF: ${join(config.dir, paths.nginx)}
    ports:
      - "${config.ports.http}:80"
      - "${config.ports.https}:443"
    extra_hosts:
      - "host.docker.internal:host-gateway"
    volumes:
      - ${config.dir}:${config.dir}
    networks:
      - ${config.network}

networks:
  ${config.network}:
    external: true
`
}

// The hosts a group's certificate must cover: its terminated routes only, since a passthrough upstream presents its own.
export const certHosts = (routes: Route[]): string[] => [...new Set(routes.filter(route => route.passthrough !== true).map(route => route.host))].sort()
